  .a-float { animation: float 4s ease-in-out infinite; transform-origin: center; }
  .a-blink { animation: blink 5s ease-in-out infinite; transform-origin: center; }
  .a-sway  { animation: sway 4.5s ease-in-out infinite; transform-origin: 50% 90%; }
  .a-pop   { animation: pop .7s cubic-bezier(.2,1.3,.4,1) both; }
