  chips.forEach(function (chip) {
    chip.addEventListener('click', function () { applyFilter(chip.getAttribute('data-filter')); });
  });

  // ---- Global motion toggle (freeze/resume all asset animations) ----
  var motionBtn = document.getElementById('motionToggle');
  if (motionBtn) {
    motionBtn.addEventListener('click', function () {
      var paused = document.body.classList.toggle('motion-paused');
      motionBtn.setAttribute('aria-pressed', String(paused));
      motionBtn.setAttribute('aria-label', paused ? 'Resume all asset animations' : 'Pause all asset animations');
    });
  }

  // ---- Dark-stage preview toggle (flip every stage to a dark product surface) ----
  var stageBtn = document.getElementById('stageToggle');
  if (stageBtn) {
    stageBtn.addEventListener('click', function () {
      var dark = document.body.classList.toggle('stage-dark');
      stageBtn.setAttribute('aria-pressed', String(dark));
      stageBtn.setAttribute('aria-label', dark ? 'Preview assets on a light surface' : 'Preview assets on a dark surface');
    });
  }

  // ---- Reduce-motion preview toggle (force the static prefers-reduced-motion fallback) ----
  var reduceBtn = document.getElementById('reduceToggle');
  if (reduceBtn) {
    reduceBtn.addEventListener('click', function () {
      var reduced = document.body.classList.toggle('motion-reduced');
      reduceBtn.setAttribute('aria-pressed', String(reduced));
      reduceBtn.setAttribute('aria-label', reduced ? 'Restore full motion' : 'Preview the reduced-motion fallback');
    });
  }
})();
</script>
</body>

